{
  if ($jabsEngine.absEnabled)
  {
    const mapId = $gameMap.mapId();
    const {x} = $gamePlayer;
    const {y} = $gamePlayer;
    $gamePlayer.reserveTransfer(mapId, x, y);
    $gamePlayer.requestMapReload();
  }
  else
  {
    // perform original logic.
    J.ABS.Aliased.Scene_Load.get('reloadMapIfUpdated')
      .call(this);
  }
};
